export const ENTERPRISE_AGENT_TEMPLATES: AgentTemplate[] = AGENT_SPECS.map((spec) => {
  const template: AgentTemplate = {
    id: spec.id,
    name: spec.name,
    category: spec.category,
    subcategory: spec.subcategory,
    specialty: spec.specialty,
    role: spec.role,
    description: spec.description,
    system_prompt: '',
    default_model: spec.model,
    provider: spec.provider,
    tags: spec.tags,
    suggested_cron: spec.cron,
    policies: spec.policies,
    recommended_mcps: spec.mcps,
    recommended_skills: spec.skills,
  };
  // Build the (large) prompt lazily the first time an agent is actually used,
  // so loading thousands of templates stays cheap.
  let cachedPrompt: string | null = null;
  Object.defineProperty(template, 'system_prompt', {
    configurable: true,
    enumerable: true,
    get() {
      if (cachedPrompt === null) cachedPrompt = buildEnhancedPrompt(spec);
      return cachedPrompt;
    },
  });
  return template;
});
